   a.previousReviewResult={text:a.text,score:a.score,checked:a.checked,rubric:[...(a.rubric||[])],reviewedAt:a.reviewedAt};
   a.rubric=[];a.checked=false;a.revealed=false;a.score=null;a.needsReviewRecheck=true;
